	@Test
	void warmedLargePairedMapsOmitReplaySpillForPendingNamespaceWrite() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		config.setTripleDBSize(64L * 1024 * 1024);
		config.setValueDBSize(64L * 1024 * 1024);
		ValueStore values = new ValueStore(new File(directory, "values"), config);
		File triplesDirectory = new File(directory, "triples");
		try (TripleStore triples = new TripleStore(triplesDirectory, config, values)) {
			for (int i = 0; i < 64; i++) {
				values.startTransaction(true);
				triples.startTransaction();
				long subject = values.storeValue(Values.iri("urn:warm:" + i));
				long predicate = values.storeValue(Values.iri("urn:predicate"));
				long object = values.storeValue(Values.literal("warm value " + i));
				triples.storeTriple(subject, predicate, object, 0, true);
				values.commit();
				triples.commit();
			}
			triples.startTransaction();
			triples.writeNamespaceSnapshot(Map.of("large", "urn:" + "n".repeat(80 * 1024)));
			try (var files = Files.list(triplesDirectory.toPath())) {
				assertEquals(0, files.filter(path -> path.getFileName().toString().startsWith("txn-replay-")).count(),
						"Warmed large paired maps should omit the complete replay journal for this pending write");
			} finally {
				triples.rollback();
			}
		} finally {
			values.close();
		}
	}

	@Test
	void repositoryCannotContinueWithASuffixAfterSkippedCommitFailure() throws Exception {
		LmdbStoreConfig config = largeConfig();
		FaultInjectingLmdbStore store = new FaultInjectingLmdbStore(directory, config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (var writer = repository.getConnection()) {
			for (int i = 0; i < 64; i++) {
				writer.begin();
				writer.add(Values.iri("urn:warm:" + i), Values.iri("urn:predicate"), Values.literal("warm " + i));
				writer.commit();
			}
			writer.begin();
			writer.add(Values.iri("urn:failed-prefix"), Values.iri("urn:predicate"), Values.literal("prefix"));
			writer.setNamespace("failed", "urn:failed-prefix:");
			store.triples.failNextCommit = true;
			RepositoryException failure = assertThrows(RepositoryException.class, writer::commit);
			assertNotNull(retryCause(failure));
			assertTrue(writer.isActive(), "The failed logical transaction still needs caller rollback");
			RepositoryException continuation = assertThrows(RepositoryException.class,
					() -> writer.add(Values.iri("urn:suffix"), Values.iri("urn:predicate"), Values.literal("suffix")),
					"Automatic native cleanup must not allow only a suffix of the logical transaction to commit");
			assertEquals(retryCause(failure), retryCause(continuation));
			RepositoryException recommit = assertThrows(RepositoryException.class, writer::commit);
			assertEquals(retryCause(failure), retryCause(recommit));
			try (var executor = Executors.newSingleThreadExecutor()) {
				executor.submit(() -> {
					RepositoryException crossThread = assertThrows(RepositoryException.class,
							() -> writer.setNamespace("suffix", "urn:suffix:"));
					assertSame(retryCause(failure), retryCause(crossThread));
				}).get();
			}
			try (var independent = repository.getConnection()) {
				independent.begin();
				independent.add(Values.iri("urn:independent"), Values.iri("urn:predicate"), Values.literal("other"));
				independent.commit();
			}
			writer.rollback();
			try (var reader = repository.getConnection()) {
				assertEquals(65, reader.size());
				assertEquals(null, reader.getNamespace("failed"));
			}
			writer.begin();
			writer.add(Values.iri("urn:failed-prefix"), Values.iri("urn:predicate"), Values.literal("prefix"));
			writer.add(Values.iri("urn:suffix"), Values.iri("urn:predicate"), Values.literal("suffix"));
			writer.setNamespace("failed", "urn:failed-prefix:");
			writer.commit();
			assertEquals(67, writer.size());
			assertEquals("urn:failed-prefix:", writer.getNamespace("failed"));
		} finally {
			repository.shutDown();
		}
		SailRepository reopened = new SailRepository(new LmdbStore(directory, config));
		reopened.init();
		try (var connection = reopened.getConnection()) {
			connection.begin();
			connection.add(Values.iri("urn:after-reopen"), Values.iri("urn:predicate"), Values.literal("reopen"));
			connection.commit();
			assertEquals(68, connection.size());
		} finally {
			reopened.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void alignedMapFullAtFirstOrLaterMutationAbortsTheWholeSkippedWrite(boolean prefix) throws Exception {
		try (PairedStores stores = new PairedStores(directory, largeConfig())) {
			stores.warm();
			stores.begin();
			if (prefix) {
				stores.triples.storeTriple(10_000, 7, 11, 9, true);
				stores.triples.writeNamespaceSnapshot(Map.of("prefix", "urn:uncommitted:"));
			}
			stores.triples.failContextCall = prefix ? 2 : 1;
			long initialMap = tripleMapSize(stores.triples);
			LmdbTransactionRetryException retry = assertThrows(LmdbTransactionRetryException.class,
					() -> stores.triples.storeTriplesAligned(new long[] { 20_000, 20_001 }, new long[] { 7, 7 },
							new long[] { 11, 11 }, new long[] { 50, 51 }, 2, true));
			assertTrue(tripleMapSize(stores.triples) > initialMap);
			assertEquals(0, stores.triples.writeTxn);
			assertEquals(64, count(stores.triples, true));
			assertEquals(Map.of(), stores.triples.readNamespaceSnapshot());
			assertSame(retry, assertThrows(LmdbTransactionRetryException.class,
					() -> stores.triples.storeTriplesAligned(new long[] { 30_000, 30_001 }, new long[] { 7, 7 },
							new long[] { 11, 11 }, new long[] { 9, 9 }, 1, true)));
			assertSame(retry, assertThrows(LmdbTransactionRetryException.class,
					() -> stores.values.storeValue(Values.iri("urn:forbidden-suffix"))));
			assertSame(retry, assertThrows(LmdbTransactionRetryException.class, stores.triples::commit));
			assertSame(retry, assertThrows(LmdbTransactionRetryException.class, stores.triples::startTransaction));
			stores.rollback();
			stores.begin();
			stores.triples.writeNamespaceSnapshot(largeNamespace());
			assertEquals(1, replayFiles(stores.triplesDirectory), "The whole retry must retain complete tracking");
			stores.triples.storeTriple(10_000, 7, 11, 9, true);
			stores.triples.storeTriplesAligned(new long[] { 20_000, 20_001 }, new long[] { 7, 7 },
					new long[] { 11, 11 }, new long[] { 50, 51 }, 2, true);
			stores.commit();
			assertEquals(67, count(stores.triples, true));
			assertEquals(largeNamespace(), stores.triples.readNamespaceSnapshot());
			assertEquals(0, replayFiles(stores.triplesDirectory));
		}
	}

