			long oldMap = stores.values.replayMapSize();
			stores.values.failNextAbortCleanup = true;
			Value large = Values.literal("v".repeat(33 * 1024 * 1024));
			LmdbTransactionRetryException retry = assertThrows(LmdbTransactionRetryException.class,
					() -> stores.values.storeValue(large));
			assertEquals("injected abort cleanup failure", retry.getSuppressed()[0].getMessage());
			assertTrue(stores.values.replayMapSize() > oldMap,
					"A cleanup error after actual abort must not prevent capacity growth for the whole retry");
			stores.rollback();
			stores.begin();
			long object = stores.values.storeValue(large);
			stores.triples.storeTriple(100_000, 7, object, 9, true);
			stores.commit();
			assertEquals(large, stores.values.getValue(object));
			assertEquals(65, count(stores.triples, true));
