	@Test
	void dictionaryRollbackCleanupFailureCannotPublishAbandonedNamespacesInAnotherWrite() throws Exception {
		FaultInjectingLmdbStore store = new FaultInjectingLmdbStore(directory, largeConfig());
		SailRepository repository = new SailRepository(store);
		repository.init();
		Object owner = new Object();
		SailSource source = store.getBackingStore().getExplicitSailSource(owner);
		try {
			try (SailSink abandoned = source.sink(IsolationLevels.NONE)) {
				abandoned.approve(Values.iri("urn:abandoned"), Values.iri("urn:predicate"),
						Values.literal("abandoned"), null);
				abandoned.setNamespace("abandoned", "urn:abandoned:");
				store.values.failNextCacheCleanup = true;
				assertThrows(SailException.class, () -> store.getBackingStore().rollback(owner));
			}
			SailSource independent = store.getBackingStore().getExplicitSailSource(new Object());
			try (SailSink committed = independent.sink(IsolationLevels.NONE)) {
				committed.approve(Values.iri("urn:committed"), Values.iri("urn:predicate"),
						Values.literal("committed"), null);
				committed.flush();
			}
			try (var reader = repository.getConnection()) {
				assertEquals(1, reader.size());
				assertEquals(null, reader.getNamespace("abandoned"),
						"Cleanup errors after abort must still discard the entire namespace write");
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void closingFailedDirectSinksReleasesOnlyTheirPrivatePoisonOwners() throws Exception {
		FaultInjectingLmdbStore store = new FaultInjectingLmdbStore(directory, largeConfig());
		store.init();
		try {
			SailSource source = store.getBackingStore().getExplicitSailSource();
			for (int cycle = 0; cycle < 3; cycle++) {
				for (int i = 0; i < 64; i++) {
					try (SailSink warm = source.sink(IsolationLevels.NONE)) {
						warm.approve(Values.iri("urn:direct-warm:" + cycle + ":" + i), Values.iri("urn:predicate"),
								Values.literal("warm " + cycle + ":" + i), null);
						warm.flush();
					}
				}
				Object privateOwner;
				try (SailSink failed = source.sink(IsolationLevels.NONE)) {
					failed.approve(Values.iri("urn:abandoned-direct:" + cycle), Values.iri("urn:predicate"),
							Values.literal("abandoned"), null);
					store.triples.failNextCommit = true;
					SailException failure = assertThrows(SailException.class, failed::flush);
					assertNotNull(retryCause(failure));
					privateOwner = store.lastCheckedOwner;
					assertSame(retryCause(failure), retryCause(assertThrows(SailException.class,
							() -> store.getBackingStore().checkWriterTransaction(privateOwner))));
				}
				assertDoesNotThrow(() -> store.getBackingStore().checkWriterTransaction(privateOwner),
						"A closed direct sink must not leave its private owner retained in the failed-writer map");
			}
			assertEquals(192, count(store.triples, true));
			try (SailSink recovered = source.sink(IsolationLevels.NONE)) {
				recovered.approve(Values.iri("urn:direct-after-recovery"), Values.iri("urn:predicate"),
						Values.literal("recovered"), null);
				recovered.flush();
			}
			assertEquals(193, count(store.triples, true));
		} finally {
			store.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void anonymousPublicationAndPreparedOwnersRetireOnlyAtTheirFinalScope(boolean prepared) throws Exception {
		FaultInjectingLmdbStore store = new FaultInjectingLmdbStore(directory, largeConfig());
		store.init();
		try {
			SailSource source = store.getBackingStore().getExplicitSailSource();
			for (int i = 0; i < 64; i++) {
				try (SailSink warm = source.sink(IsolationLevels.NONE)) {
					warm.approve(Values.iri("urn:scope-warm:" + i), Values.iri("urn:predicate"),
							Values.literal("warm " + i), null);
					warm.flush();
				}
			}
			Value large = Values.literal("v".repeat(33 * 1024 * 1024));
			Object owner;
			try (SailClosable outerPrepared = prepared ? source.beginPreparedWrite() : () -> {
			};
					SailClosable innerPrepared = prepared ? source.beginPreparedWrite() : () -> {
					}) {
				try (SailClosable publication = source.beginPublication()) {
					try (SailSink failed = source.sink(IsolationLevels.NONE)) {
						failed.approve(Values.iri("urn:scope-prefix"), Values.iri("urn:predicate"),
								Values.literal("prefix"), null);
						failed.setNamespace("scope", "urn:scope:");
						owner = store.lastCheckedOwner;
						SailException failure = assertThrows(SailException.class,
								() -> failed.approve(Values.iri("urn:scope-large"), Values.iri("urn:predicate"), large,
										null));
						assertNotNull(retryCause(failure));
					}
					assertNotNull(retryCause(assertThrows(SailException.class,
							() -> store.getBackingStore().checkWriterTransaction(owner))),
							"An intermediate sink close cannot retire its still-open publication owner");
				}
				if (prepared) {
					assertThrows(SailException.class, () -> store.getBackingStore().checkWriterTransaction(owner));
					innerPrepared.close();
					assertThrows(SailException.class, () -> store.getBackingStore().checkWriterTransaction(owner),
							"A nested prepared close must retain failure until the final reference closes");
				}
			}
			assertDoesNotThrow(() -> store.getBackingStore().checkWriterTransaction(owner),
					"Internally created owners must be retired when their complete logical scope ends");
			assertEquals(64, count(store.triples, true));
			assertEquals(Map.of(), store.triples.readNamespaceSnapshot());
			try (SailSink retried = source.sink(IsolationLevels.NONE)) {
				retried.approve(Values.iri("urn:scope-prefix"), Values.iri("urn:predicate"),
						Values.literal("prefix"), null);
				retried.approve(Values.iri("urn:scope-large"), Values.iri("urn:predicate"), large, null);
				retried.setNamespace("scope", "urn:scope:");
				retried.flush();
			}
			assertEquals(66, count(store.triples, true));
			assertEquals(Map.of("scope", "urn:scope:"), store.triples.readNamespaceSnapshot());
		} finally {
			store.shutDown();
		}
	}

	@Test
	void delayedAsyncWriterCannotCreateAnOwnerlessFailureAfterDictionaryStartupExhaustion() throws Exception {
		// This fault fixture requires async startup; disabled bulk retains the direct scalar scheduling preference.
		FaultInjectingLmdbStore store = new FaultInjectingLmdbStore(directory, largeConfig().setBulkOperationSize(0));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (var writer = repository.getConnection()) {
			for (int i = 0; i < 64; i++) {
				writer.begin();
				writer.add(Values.iri("urn:startup-warm:" + i), Values.iri("urn:predicate"),
						Values.literal("warm " + i));
				writer.commit();
			}
			CountDownLatch entered = new CountDownLatch(1);
			CountDownLatch resume = new CountDownLatch(1);
			store.triples.delayedStartEntered = entered;
			store.triples.resumeDelayedStart = resume;
			Value large = Values.literal("v".repeat(33 * 1024 * 1024));
			store.values.failStartupValue = large;
			store.values.delayedStartEntered = entered;
			store.values.resumeDelayedStartOnRollback = resume;
			writer.begin();
			writer.add(Values.iri("urn:startup-prefix"), Values.iri("urn:predicate"), Values.literal("prefix"));
			RepositoryException failure;
			try {
				failure = assertThrows(RepositoryException.class, writer::commit);
			} finally {
				resume.countDown();
			}
			assertNotNull(retryCause(failure));
			assertSame(retryCause(failure), retryCause(assertThrows(RepositoryException.class,
					() -> writer.setNamespace("forbidden", "urn:forbidden:"))));
			assertDoesNotThrow(() -> store.getBackingStore().checkWriterTransaction(null),
					"A delayed worker must not retain its retry against a lost, null writer owner");
			try (var independent = repository.getConnection()) {
				independent.begin();
				independent.add(Values.iri("urn:startup-independent"), Values.iri("urn:predicate"),
						Values.literal("independent"));
				independent.commit();
				assertEquals(65, independent.size());
			}
			writer.rollback();
			writer.begin();
			writer.add(Values.iri("urn:startup-prefix"), Values.iri("urn:predicate"), Values.literal("prefix"));
			writer.add(Values.iri("urn:startup-large"), Values.iri("urn:predicate"), large);
			writer.commit();
			assertEquals(67, writer.size());
		} finally {
			repository.shutDown();
		}
	}

