	@Test
	void pinnedReaderChurnUsesHighWaterGrowthDespiteSmallLiveContents() throws Exception {
		try (PairedStores stores = new PairedStores(directory, largeConfig());
				var tripleReservation = stores.triples.getTxnManager().reserveReadTxn(false);
				var valueReservation = stores.values.reserveReadSnapshot()) {
			stores.warm();
			try (var pinnedTriples = tripleReservation.startPinned(stores.triples::getDataRevision);
					var pinnedValues = valueReservation.start()) {
				int batchSize = 100_000;
				long[] subjects = new long[batchSize];
				long[] predicates = new long[batchSize];
				long[] objects = new long[batchSize];
				long[] contexts = new long[batchSize];
				Arrays.fill(predicates, 7);
				Arrays.fill(objects, 11);
				Arrays.fill(contexts, 90);
				for (int cycle = 0; cycle < 2; cycle++) {
					for (int i = 0; i < batchSize; i++) {
						subjects[i] = 100_000L + (long) cycle * batchSize + i;
					}
					stores.begin();
					stores.triples.storeTriplesAligned(subjects, predicates, objects, contexts, batchSize, true);
					stores.commit();
					stores.begin();
					stores.triples.removeTriplesByContext(-1, -1, -1, 90, true, ignored -> {
					});
					stores.commit();
				}
				assertEquals(64, count(stores.triples, true), "Removed pages do not make the high-water mark low");
				try (var iterator = stores.triples.getTriples(pinnedTriples, -1, -1, -1, -1, true)) {
					int oldCount = 0;
					while (iterator.next() != null) {
						oldCount++;
					}
					assertEquals(64, oldCount);
				}
				assertTrue(pinnedValues.isCurrent());
				stores.triples.startTransaction();
				stores.triples.writeNamespaceSnapshot(largeNamespace());
				assertEquals(1, replayFiles(stores.triplesDirectory),
						"Recent page growth while old readers pin reuse must keep complete replay tracking");
				stores.rollback();
			}
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void committedHighWaterIncludesNativeCommitAllocationsWithPinnedReaders(boolean dictionary) throws Exception {
		try (PairedStores stores = new PairedStores(directory, largeConfig());
				var tripleReservation = stores.triples.getTxnManager().reserveReadTxn(false);
				var valueReservation = stores.values.reserveReadSnapshot()) {
			stores.warm();
			try (var pinnedTriples = tripleReservation.startPinned(stores.triples::getDataRevision);
					var pinnedValues = valueReservation.start()) {
				for (int cycle = 0; cycle < 8; cycle++) {
					stores.begin();
					long subject = stores.values.storeValue(Values.iri("urn:pinned-allocation:" + cycle));
					long object = stores.values.storeValue(Values.literal("pinned allocation " + cycle));
					stores.triples.storeTriple(subject, 7, object, 90, true);
					stores.commit();
					assertCommittedHighWater(stores, dictionary);
					stores.begin();
					stores.triples.removeTriplesByContext(-1, -1, -1, 90, true, ignored -> {
					});
					stores.values.gcIds(Set.of(subject, object), new HashSet<>());
					stores.commit();
					assertCommittedHighWater(stores, dictionary);
				}
				assertEquals(64, count(stores.triples, true));
				assertTrue(pinnedValues.isCurrent());
			}
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void skippedNamespaceCapacityAtFirstOrLaterMutationRequiresCompleteRetry(boolean prefix) throws Exception {
		try (PairedStores stores = new PairedStores(directory, largeConfig())) {
			stores.warm();
			Map<String, String> huge = Map.of("huge", "urn:" + "n".repeat(65 * 1024 * 1024));
			stores.begin();
			if (prefix) {
				stores.triples.storeTriple(100_000, 7, 11, 9, true);
			}
			long beforeMap = tripleMapSize(stores.triples);
			LmdbTransactionRetryException retry = assertThrows(LmdbTransactionRetryException.class,
					() -> stores.triples.writeNamespaceSnapshot(huge));
			assertTrue(tripleMapSize(stores.triples) > beforeMap);
			assertSame(retry, assertThrows(LmdbTransactionRetryException.class, stores.triples::commit));
			assertEquals(64, count(stores.triples, true));
			assertEquals(Map.of(), stores.triples.readNamespaceSnapshot());
			stores.rollback();
			stores.begin();
			if (prefix) {
				stores.triples.storeTriple(100_000, 7, 11, 9, true);
			}
			stores.triples.writeNamespaceSnapshot(huge);
			assertEquals(1, replayFiles(stores.triplesDirectory));
			stores.commit();
			assertEquals(prefix ? 65 : 64, count(stores.triples, true));
			assertEquals(huge, stores.triples.readNamespaceSnapshot());
		}
	}

