	@Test
	void nativeMapFullClassificationAndDisabledGrowthRemainUnchanged() throws Exception {
		IOException classified = assertThrows(LmdbUtil.MapFullException.class, () -> LmdbUtil.E(MDB_MAP_FULL));
		assertEquals(mdb_strerror(MDB_MAP_FULL), classified.getMessage());
		try (PairedStores stores = new PairedStores(directory, largeConfig().setAutoGrow(false))) {
			stores.begin();
			stores.triples.storeTriple(1, 7, 11, 0, true);
			long tripleMap = tripleMapSize(stores.triples);
			stores.triples.failNextCommit = true;
			IOException failure = assertThrows(LmdbUtil.MapFullException.class, stores.triples::commit);
			assertEquals(mdb_strerror(MDB_MAP_FULL), failure.getMessage());
			assertEquals(tripleMap, tripleMapSize(stores.triples));
			assertThrows(IllegalStateException.class,
					() -> stores.triples.storeTriplesAligned(new long[] { 1 }, new long[] { 7 },
							new long[] { 11 }, new long[] { 0 }, 1, true));
			stores.rollback();
			stores.begin();
			stores.values.storeValue(Values.iri("urn:disabled-commit"));
			long valueMap = stores.values.replayMapSize();
			stores.values.failNextCommit = true;
			failure = assertThrows(LmdbUtil.MapFullException.class, stores.values::commit);
			assertEquals(mdb_strerror(MDB_MAP_FULL), failure.getMessage());
			assertEquals(valueMap, stores.values.replayMapSize());
			stores.rollback();
		}
	}

